() => {
  const store = JSON.parse(localStorage.getItem('analytics-store'));
  const keys = Object.keys(store.state);
  const interesting = {};
  keys.forEach(k => {
    if (/acc|acl|restrict|denied|grant|pending|request/i.test(k)) {
      const v = store.state[k];
      interesting[k] = typeof v === 'object' ? JSON.stringify(v).slice(0, 500) : v;
    }
  });
  return { allKeys: keys, interesting };
}

