  const list = Array.isArray(data) ? data : (data.dataSources || data.items || []);
  return list.map(d => ({ id: d.id, name: d.name, accessDenied: d.accessDenied === true, tableCount: d.tableCount, tablesLen: (d.tables||[]).length }));
}

